import { AESModeOfOperationCBC } from './lib/aes/cbc.mjs';
import { parseCommandLine } from './lib/cli/parser.mjs';
import { ValueError } from './lib/errors.mjs';
import { formatPythonBytes } from './lib/format/python_bytes.mjs';

const ENCODER = new TextEncoder();

function encodeUtf8(value) {
  return ENCODER.encode(value);
}

export function main(argv = process.argv.slice(2), programPath = process.argv[1]) {
  const parseResult = parseCommandLine(argv, programPath);

  if (parseResult.kind === 'help') {
    process.stdout.write(parseResult.text);
    return 0;
  }

  if (parseResult.kind === 'error') {
    process.stderr.write(parseResult.text);
    return parseResult.status;
  }

  try {
    const aes = new AESModeOfOperationCBC(
      encodeUtf8(parseResult.values.key),
      encodeUtf8(parseResult.values.iv),
    );
    const ciphertext1 = aes.encrypt(encodeUtf8(parseResult.values.data1));
    const ciphertext2 = aes.encrypt(encodeUtf8(parseResult.values.data2));

    console.log(formatPythonBytes(ciphertext1));
    console.log(formatPythonBytes(ciphertext2));
    return 0;
  } catch (error) {
    if (error instanceof ValueError) {
      process.stderr.write(`${error.name}: ${error.message}\n`);
      return 1;
    }

    throw error;
  }
}

const exitCode = main();
if (exitCode !== 0) {
  process.exit(exitCode);
}

