function rotateLeft8(value, shift) {
  return ((value << shift) | (value >>> (8 - shift))) & 0xff;
}

export function xtime(value) {
  const shifted = value << 1;
  return ((value & 0x80) !== 0 ? shifted ^ 0x11b : shifted) & 0xff;
}

export function multiply(left, right) {
  let result = 0;
  let a = left & 0xff;
  let b = right & 0xff;

  while (b > 0) {
    if ((b & 1) !== 0) {
      result ^= a;
    }
    a = xtime(a);
    b >>>= 1;
  }

  return result & 0xff;
}

function power(base, exponent) {
