  let factor = base;
  let remaining = exponent;

  while (remaining > 0) {
    if ((remaining & 1) !== 0) {
      result = multiply(result, factor);
    }
    factor = multiply(factor, factor);
    remaining >>>= 1;
  }

  return result;
}

function multiplicativeInverse(value) {
