export function formatPythonValueError(stage, message) {
  const commonFrames = [
    '  File "test7.py", line 21, in <module>',
  ];

  if (stage === 'constructor') {
    if (message === 'initialization vector must be 16 bytes') {
      return buildTraceback(
        [
          ...commonFrames,
          '  File "test7.py", line 13, in main',
          '  File "pyaes/aes.py", line 381, in __init__',
        ],
        message,
      );
    }

    if (message === 'Invalid key size') {
      return buildTraceback(
        [
          ...commonFrames,
          '  File "test7.py", line 13, in main',
          '  File "pyaes/aes.py", line 385, in __init__',
          '  File "pyaes/aes.py", line 304, in __init__',
          '  File "pyaes/aes.py", line 134, in __init__',
        ],
        message,
      );
    }
  }

  if (message === 'plaintext block must be 16 bytes') {
    const lineNumber = stage === 'data2' ? 16 : 15;
    return buildTraceback(
      [
        ...commonFrames,
        `  File "test7.py", line ${lineNumber}, in main`,
        '  File "pyaes/aes.py", line 389, in encrypt',
      ],
      message,
    );
  }

  return `ValueError: ${message}\n`;
}

